func main(){scanner:=bufio.NewScanner(os.Stdin);scanner.Buffer(make([]byte,4096),1<<20);enc:=json.NewEncoder(os.Stdout);for scanner.Scan(){var row struct{Name string `json:"name"`;Type string `json:"type"`;Hex string `json:"hex"`};if err:=json.Unmarshal(scanner.Bytes(),&row);err!=nil{panic(err)};out:=map[string]any{"name":row.Name,"type":row.Type};wire,err:=hex.DecodeString(row.Hex);if err!=nil{panic(err)};typ,err:=protoregistry.GlobalTypes.FindMessageByName(protoreflect.FullName(row.Type));if err!=nil{panic(err)};m:=typ.New().Interface();if err:=proto.Unmarshal(wire,m);err!=nil{out["accepted"]=false;out["error"]=err.Error()}else{out["accepted"]=true;full,err:=proto.Marshal(m);if err!=nil{panic(err)};out["wire_base64"]=base64.StdEncoding.EncodeToString(full);discardUnknown(m.ProtoReflect());known,err:=proto.Marshal(m);if err!=nil{panic(err)};out["known_wire_base64"]=base64.StdEncoding.EncodeToString(known);j,err:=protojson.Marshal(m);if err!=nil{panic(err)};out["known_json"]=json.RawMessage(j)};if err:=enc.Encode(out);err!=nil{panic(err)}};if err:=scanner.Err();err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(1)}}
